 private void select(int index){if(section==index&&PageNavigator.current(pager)==index)return;section=index;selected="";selectedItem=null;if(reader!=null){reader.dispose();reader=null;}emptyReader();PageNavigator.select(pager,index);updateNav();filterAll();reflow(body.getWidth());}
 private void updateNav(){section=PageNavigator.current(pager);title.setText(section==0?"通知":"系统消息");for(int i=0;i<2;i++){TextView[] views=i==0?new TextView[]{navNotice,railNotice}:new TextView[]{navSystem,railSystem};for(TextView v:views){boolean active=i==section;v.setTextColor(active?colors.onPrimary:colors.muted);v.setBackgroundDrawable(Ui.ripple(a,active?colors.primary:colors.container,active?24:16));v.setSelected(active);}}}
 private static Object value(Object v,Object fallback){return v==null?fallback:v;}
