 public static void pageSelected(Activity a,int index){if(index<0||index>1)return;NoticeShell p=pages.get(a);if(p==null||p.disposed)return;if(p.section!=index){p.section=index;p.selected="";p.selectedItem=null;if(p.reader!=null){p.reader.dispose();p.reader=null;}p.emptyReader();}p.updateNav();p.reflow(p.body.getWidth());}
 public static void configuration(Activity a){NoticeShell p=pages.get(a);if(p==null)return;if(new Ui.Colors(a).dark==p.colors.dark){Ui.inset(a);return;}Object item=p.selectedItem;Bundle state=new Bundle();save(a,state);p.disposed=true;if(p.reader!=null)p.reader.dispose();pages.remove(a);install(a,state);if(item!=null)open(a,item);}
 public static void install(Activity a,Bundle saved){try{if(pages.containsKey(a))return;NoticeShell shell=new NoticeShell(a);pages.put(a,shell);PageNavigator.install(a,shell.pager);if(saved!=null){int tab=saved.getInt("m3e_section",0);shell.select(tab);shell.search.setText(saved.getString("m3e_query",""));shell.selected=saved.getString("m3e_selected","");}}catch(Exception e){android.util.Log.e("NoticeM3e","Cannot build native shell",e);}}
