 public static boolean back(Activity a){NoticeShell p=pages.get(a);if(p==null||p.selectedItem==null)return false;p.selected="";p.selectedItem=null;if(p.reader!=null)p.reader.dispose();p.reader=null;p.emptyReader();p.filterAll();p.reflow(p.body.getWidth());return true;}
