 public static void destroy(Activity a){NoticeShell p=pages.remove(a);if(p!=null){p.disposed=true;PageNavigator.detach(p.pager);PageNavigator.detach(p.pager);PageNavigator.detach(p.pager);if(p.reader!=null)p.reader.dispose();Iterator<Object> it=originals.keySet().iterator();while(it.hasNext())if(owner(it.next())==a)it.remove();}}
 private static Activity owner(Object adapter){Object c=Data.field(adapter,"context");while(c instanceof ContextWrapper&&!(c instanceof Activity)){Context next=((ContextWrapper)c).getBaseContext();if(next==c)break;c=next;}return c instanceof Activity?(Activity)c:null;}
